B.cXa=new A.p("layout",B.bF,"Layout: piles/fan stacks; grid = a centered wrapping tableau.",B.bA1,null)
B.cZ7=new A.p("filter",B.V,"Optional node-local filter {column, value} or {column, in:[...]}.",B.f,null)
B.d00=new A.p("pileOrder",B.V,"Pinned pile order (a list of pileColumn values; shown even if empty).",B.f,null)
B.cH2=new A.p("pileLabels",B.V,"Map of pile value \u2192 display label.",B.f,null)
B.cVJ=new A.p("cardWidth",B.af,"Card width in logical px (default 64).",B.f,null)
B.cYi=new A.p("fan",B.af,"Overlap fraction for stacked/fanned cards (default 0.18).",B.f,null)
B.cJJ=new A.p("maxStack",B.af,"Max cards drawn for a stacked pile; deeper piles show top N + a count (default 6). Hands (fan) and grids are never capped.",B.f,null)
B.cYf=new A.p("fontFamily",B.E,"Font for rank/court letters (suits are vector-drawn). Default: system.",B.f,null)
B.d_f=new A.p("onTap",B.V,"Card-tap action spec { fn, args }.",B.f,null)
B.d0h=new A.p("action",B.V,"Alias for `onTap` (card-tap action spec { fn, args }); either name works.",B.f,null)
