B.cwu=new A.d1("cardtable","A felt table of real playing-card faces, grouped into piles from a table of card rows (one row per card). Cards slide between piles and flip on faceUp changes; rules stay in the data functions.",B.bAy,!1)
B.cPe=new A.p("table",B.at,"Dice table (one row per die).",B.f,null)
B.cY2=new A.p("valueColumn",B.t,'Numeric face-value column (default "value").',B.f,null)
B.cUK=new A.p("heldColumn",B.t,"Optional bool column; held dice show a ring and do not tumble.",B.f,null)
B.cRv=new A.p("sides",B.af,"Die sides, for the roll-through flash (default 6).",B.f,null)
B.cZ0=new A.p("dieSize",B.af,"Die edge in logical px (default 64).",B.f,null)
B.cJA=new A.p("onTap",B.V,"Die-tap action spec { fn, args }.",B.f,null)
